/// True when `value` names exactly one ordinary path component, so joining it
/// onto a directory cannot address anything outside that directory.
fn is_single_path_component(value: &str) -> bool {
    let mut components = std::path::Path::new(value).components();
    matches!(components.next(), Some(std::path::Component::Normal(_)))
        && components.next().is_none()
}

/// Collect audio filenames from a directory, returning an empty Vec if
/// the directory doesn't exist or contains no audio files.
fn collect_audio_filenames(dir: &std::path::Path) -> Vec<String> {
    let mut filenames = Vec::new();
    let Ok(entries) = std::fs::read_dir(dir) else {
        return filenames;
    };
    for entry in entries.flatten() {
        let Ok(file_type) = entry.file_type() else {
            continue;
        };
        if !file_type.is_file() {
            continue;
        };
        let name = entry.file_name().to_string_lossy().into_owned();
        let is_audio = std::path::Path::new(&name)
            .extension()
            .and_then(|ext| ext.to_str())
            .map(|ext| {
                crate::scanner::KNOWN_AUDIO_EXTENSIONS.contains(&ext.to_lowercase().as_str())
            })
            .unwrap_or(false);
        if is_audio {
            filenames.push(name);
        }
    }
    filenames
}

