#[test]
fn a_spelling_that_differs_only_by_an_apostrophe_is_the_same_album() {
    // The reported duplication. The library held the album under a tag with
    // no apostrophe at all, while MusicBrainz reported two release groups —
    // "Sgt. Pepper’s Lonely Hearts Club Band" (U+2019, 1967) and "Sgt.
    // Pepper's Lonely Hearts Club Band" (ASCII, 2009). Every spelling was a
    // distinct key, so discover judged the album missing twice in one run,
    // downloaded it twice and placed two new folders beside the first.
    let index = build_index(&[scanned("The Beatles", "Sgt. Peppers Lonely Hearts Club Band")]);
    assert!(
        index.contains_album("The Beatles", "Sgt. Pepper\u{2019}s Lonely Hearts Club Band"),
        "the curly-apostrophe MusicBrainz title must find the apostrophe-less tag"
    );
    assert!(
        index.contains_album("The Beatles", "Sgt. Pepper's Lonely Hearts Club Band"),
        "the ASCII-apostrophe MusicBrainz title must find the apostrophe-less tag"
    );
}

#[test]
fn keys_are_normalised_but_punctuation_stays_significant() {

/// Apostrophe characters that spell the same mark across keyboards, tags and
/// cover art: the ASCII apostrophe, the typographic pair, the single high
/// quotation mark, the modifier letter apostrophe, the grave accent and the
/// acute accent.
///
/// They are removed before folding so `Guns N’ Roses` (how MusicBrainz spells
/// it), `Guns 'n' Roses` (how one library spells it) and `Guns N Roses` share a
/// single key. Leaving them in made one album look like several: a discover run
/// reported both MusicBrainz Sgt. Pepper release groups, the library's
/// apostrophe-less tag did not match either, and the album was downloaded twice
/// into two new folders beside the copy already on disk.
const APOSTROPHE_LIKE_CHARACTERS: [char; 7] =
    ['\'', '\u{2018}', '\u{2019}', '\u{201B}', '\u{02BC}', '`', '\u{00B4}'];

pub(crate) fn normalize_catalog_key(value: &str) -> String {
    value
        .chars()
        .filter(|character| !APOSTROPHE_LIKE_CHARACTERS.contains(character))
        .collect::<String>()
        .nfkc()
        .flat_map(char::to_lowercase)
        .collect::<String>()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}

