"""Temp verification helper: mutate the fix, confirm the tests bite, restore byte-identically."""

import hashlib
import pathlib
import shutil
import subprocess
import sys

REPO = pathlib.Path("/data/seakarr")
FILES = [REPO / "src/discography/mod.rs", REPO / "src/discover.rs"]
BACKUP = pathlib.Path("/tmp/verify_backup")


def sha(paths):
    return {p.name: hashlib.sha256(p.read_bytes()).hexdigest() for p in paths}


def backup():
    BACKUP.mkdir(exist_ok=True)
    for p in FILES:
        shutil.copy2(p, BACKUP / p.name)


def restore():
    for p in FILES:
        shutil.copy2(BACKUP / p.name, p)


def sub(path, old, new, label):
    text = path.read_text()
    if text.count(old) != 1:
        sys.exit(f"FAIL: {label} anchor appears {text.count(old)} times in {path.name}")
    path.write_text(text.replace(old, new))


def run_lib_tests():
    proc = subprocess.run(
        ["cargo", "test", "--lib"], cwd=REPO, capture_output=True, text=True
    )
    out = proc.stdout + proc.stderr
    failures = [
        line.strip()
        for line in out.splitlines()
        if line.startswith("    ") and "::" in line and " " not in line.strip()
    ]
    return proc.returncode, sorted(set(failures))


MUTATIONS = {
    "apostrophe-fold": (
        "discography/mod.rs",
        "const APOSTROPHE_LIKE_CHARACTERS: [char; 7] = [\n"
        "    '\\'', '\\u{2018}', '\\u{2019}', '\\u{201B}', '\\u{02BC}', '`', '\\u{00B4}',\n"
        "];",
        "const APOSTROPHE_LIKE_CHARACTERS: [char; 1] = ['\\''];",
