    ),
    "presence-identity": (
        "discover.rs",
        "let album_key = album_identity_key(album, artist);",
        "let album_key = normalize_catalog_key(album);",
    ),
}

if __name__ == "__main__":
    original = sha(FILES)
    backup()
    print(f"baseline sha256: {original}")

    name = sys.argv[1]
    filename, old, new = MUTATIONS[name]
    target = REPO / "src" / filename
    sub(target, old, new, name)
    code, failures = run_lib_tests()
    restore()

    restored = sha(FILES)
    print(f"mutation            : {name}")
    print(f"cargo test --lib rc : {code}")
    print(f"failed tests ({len(failures)}):")
    for f in failures:
        print(f"   - {f}")
    print(f"restored byte-identical: {restored == original}")

