            .map_err(Into::into)
    }

    pub fn upsert_discography_cache(&self, entry: &DiscographyCacheEntry) -> Result<()> {
        self.conn.execute(
            "INSERT INTO discography_cache
             (artist_key, artist_mbid, canonical_artist, fetched_at, release_groups_json)
             VALUES (?1, ?2, ?3, ?4, ?5)
             ON CONFLICT(artist_key) DO UPDATE SET
               artist_mbid = excluded.artist_mbid,
               canonical_artist = excluded.canonical_artist,
               fetched_at = excluded.fetched_at,
               release_groups_json = excluded.release_groups_json",
            params![
                entry.artist_key,
                entry.artist_mbid,
                entry.canonical_artist,
                entry.fetched_at,
                entry.release_groups_json,
            ],
        )?;
        Ok(())
    }

    pub fn delete_discography_cache(&self, artist_key: &str) -> Result<bool> {
        Ok(self.conn.execute(
            "DELETE FROM discography_cache WHERE artist_key = ?1 COLLATE NOCASE",
            params![artist_key],
        )? > 0)
    }

    /// Read the recorded resolution failure for `artist_key`, if there is one.
    pub fn get_discography_failure(
        &self,
        artist_key: &str,
    ) -> Result<Option<DiscographyFailureEntry>> {
        self.conn
            .query_row(
                "SELECT artist_key, failure_kind, reason, recorded_at
                 FROM discography_failures WHERE artist_key = ?1 COLLATE NOCASE",
                params![artist_key],
                |row| {
                    Ok(DiscographyFailureEntry {
                        artist_key: row.get(0)?,
                        failure_kind: row.get(1)?,
                        reason: row.get(2)?,
                        recorded_at: row.get(3)?,
                    })
                },
            )
            .optional()
            .map_err(Into::into)
    }

    /// Record a resolution failure for `artist_key`, replacing any earlier one.
    pub fn upsert_discography_failure(&self, entry: &DiscographyFailureEntry) -> Result<()> {
        self.conn.execute(
            "INSERT INTO discography_failures
             (artist_key, failure_kind, reason, recorded_at)
             VALUES (?1, ?2, ?3, ?4)
             ON CONFLICT(artist_key) DO UPDATE SET
               failure_kind = excluded.failure_kind,
               reason = excluded.reason,
               recorded_at = excluded.recorded_at",
            params![
                entry.artist_key,
                entry.failure_kind,
                entry.reason,
                entry.recorded_at,
            ],
        )?;
        Ok(())
    }

    /// Delete the recorded failure for `artist_key`; true when a row was removed.
    pub fn delete_discography_failure(&self, artist_key: &str) -> Result<bool> {
        Ok(self.conn.execute(
            "DELETE FROM discography_failures WHERE artist_key = ?1 COLLATE NOCASE",
            params![artist_key],
        )? > 0)
