#[test]
fn pid_lock_refuses_a_pid_path_that_cannot_be_read() {
    // A directory at the PID path makes `create_new` report AlreadyExists,
    // and then reading it as a PID fails. Liveness cannot be verified, so the
    // lock must refuse rather than overwrite a possibly-live lock.
    let temp = TempDir::new().unwrap();
    let pid_file = temp.path().join("seakarr.pid");
    std::fs::create_dir(&pid_file).unwrap();

    let error = acquire_pid_lock(&pid_file)
        .expect_err("an unreadable PID path must be refused");
    assert!(
        matches!(error, SeakarrError::PidLock(_)),
        "expected a PidLock error, got {error:?}"
    );
    assert!(
        pid_file.is_dir(),
        "refusing the lock must leave the path untouched"
    );
}

