pub(crate) fn normalize_catalog_key(value: &str) -> String {
    // The filter runs on BOTH sides of the compatibility fold. Before it, so a
    // mark that decomposes into something else is removed while it is still one
    // character (U+00B4 becomes a space plus a combining acute). After it, so a
    // compatibility variant that NFKC turns INTO a listed mark is removed too:
